def p(text,style='BodyA'): return Paragraph(text,styles[style])
def bullets(items): return [p('• '+x) for x in items]
def table(rows,widths,header=True):
    data=[[p(str(v),'CellBoldA' if header and ri==0 else 'CellA') for v in row] for ri,row in enumerate(rows)]
    st=[('GRID',(0,0),(-1,-1),.35,GRID),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F9FC')])]
    if header: st += [('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white)]
    return Table(data,colWidths=widths,repeatRows=1 if header else 0,style=st)
def callout(title,text,color=PALE):
    t=Table([[p(title,'CellBoldA')],[p(text,'BodyA')]],colWidths=[170*mm],style=[('BACKGROUND',(0,0),(-1,-1),color),('BOX',(0,0),(-1,-1),.8,BLUE),('PADDING',(0,0),(-1,-1),7)])
    return KeepTogether([t,Spacer(1,3*mm)])
class Architecture(Flowable):
    def __init__(self): super().__init__();self.width=170*mm;self.height=78*mm
    def box(self,x,y,w,h,title,sub,color):
        c=self.canv;c.setFillColor(colors.white);c.setStrokeColor(color);c.setLineWidth(1.4);c.roundRect(x,y,w,h,6,1,1);c.setFillColor(color);c.setFont('AtlasBold',9);c.drawCentredString(x+w/2,y+h-14,title);c.setFillColor(MUTED);c.setFont('Atlas',7)
        for i,s in enumerate(sub):c.drawCentredString(x+w/2,y+h-27-i*9,s)
    def draw(self):
        c=self.canv; self.box(52*mm,52*mm,66*mm,22*mm,'SERVIDOR ATLAS POS',['IIS + ASP.NET Core 8','MySQL 8.4 en localhost'],BLUE)
        for x,t in [(2,'CAJA 1'),(60,'CAJA 2'),(118,'CAJA N')]: self.box(x*mm,5*mm,50*mm,22*mm,t,['Navegador + Atlas Agent','Báscula / impresora / cajón'],TEAL)
        c.setStrokeColor(TEAL);c.setLineWidth(1.4)
        for x in [27,85,143]:c.line(85*mm,52*mm,x*mm,27*mm)
        c.setFillColor(PALE);c.roundRect(31*mm,34*mm,108*mm,10*mm,4,1,0);c.setFillColor(NAVY);c.setFont('AtlasBold',8);c.drawCentredString(85*mm,37*mm,'LAN privada: HTTP 8080 / agente 17420')
