    canvas.saveState();canvas.setFillColor(NAVY);canvas.rect(0,letter[1]-16*mm,letter[0],16*mm,fill=1,stroke=0);canvas.setFillColor(colors.white);canvas.setFont('AtlasBold',8);canvas.drawString(20*mm,letter[1]-10*mm,'ATLAS POS - INFORME TÉCNICO');canvas.setFillColor(MUTED);canvas.setFont('Atlas',7);canvas.drawRightString(letter[0]-18*mm,9*mm,f'Página {doc.page}');canvas.restoreState()

