s += [Spacer(1,12*mm),Table([[p('ATLAS POS','TitleA')],[p('Informe técnico integral<br/>Arquitectura, lógica, tecnologías, seguridad e instalación','SubA')]],colWidths=[170*mm],style=[('BACKGROUND',(0,0),(-1,-1),NAVY),('PADDING',(0,0),(-1,-1),10*mm)]),Spacer(1,11*mm),Architecture(),Spacer(1,8*mm),callout('Propósito del documento','Describir con detalle verificable qué se construyó, cómo funciona, qué métodos se aplicaron y cuáles son los límites pendientes. Fecha de corte: 13 de agosto de 2026.',colors.HexColor('#E9F8F2'))]
s += [PageBreak(),p('1. Resumen ejecutivo','H1A'),p('Atlas POS es una aplicación web de punto de venta centralizada para operar varias cajas dentro de una red local. Una PC actúa como servidor IIS/MySQL y cada caja accede desde navegador. Los periféricos locales se conectan mediante Atlas Peripheral Agent, un servicio de Windows independiente por terminal.'),p('Resultados funcionales','H2A'),*bullets(['Venta por pieza y por unidades fraccionarias: kg, g, litro, ml, metro, caja o unidad configurada.','Productos pesables con lectura periódica de báscula, captura con tres decimales y limpieza del flujo al agregar.','Inventario central, compras, ajustes, mermas, devoluciones parciales y reingreso opcional.','Turnos de caja por usuario y terminal, entradas/retiros, corte y diferencia contra efectivo esperado.','Impresión de ticket, apertura automática o manual del cajón y auditoría de acciones sensibles.','Usuarios con roles Administrator, Manager y Cashier; terminales separadas e identidad persistente.','Instaladores reutilizables para servidor y cliente; no quedan ligados a una sola computadora ni se autoborran.']),callout('Estado general','El núcleo del sistema y los instaladores están compilados y cuentan con pruebas automatizadas y simulación de aprovisionamiento. La certificación final de periféricos exige pruebas físicas con cada modelo real, cable, controlador y configuración del establecimiento.',colors.HexColor('#FFF3E5')),p('Alcance documental','H2A'),p('Este informe cubre el código presente en el repositorio, sus migraciones, integraciones públicas, scripts de despliegue y evidencias de prueba. No representa certificación fiscal, firma de código ni homologación oficial de fabricantes.')]
s += [PageBreak(),p('2. Arquitectura de despliegue','H1A'),Architecture(),p('Componentes y responsabilidades','H2A'),table([['Componente','Responsabilidad','Comunicación'],['Servidor IIS','Interfaz MVC, autenticación, reglas de negocio, API interna y archivos del cliente','TCP 8080, perfil privado'],['MySQL','Persistencia transaccional central','TCP 3306 sólo 127.0.0.1'],['Caja cliente','Navegador, sesión, terminal y operación del cajero','HTTP hacia el servidor'],['Atlas Agent','Acceso local a COM, impresoras Windows y cajón','TCP 17420, token y firewall restringido'],['Periféricos','Peso, ticket y pulso del cajón','Serie, Windows spooler, TCP o ESC/POS']], [31*mm,85*mm,54*mm]),Spacer(1,5*mm),p('Método cliente-servidor','H2A'),p('Toda la información comercial reside en el servidor. Las cajas no se conectan a MySQL ni comparten directamente sus periféricos. El servidor identifica cada navegador mediante un terminal ID persistente y conserva configuraciones por sucursal, estación y clave de dispositivo.'),callout('Aislamiento de terminales','Turnos, ventas y periféricos contienen WorkstationId. Esto evita que la báscula o impresora de una caja se mezcle con las de otra y permite múltiples sesiones simultáneas.',PALE)]
s += [PageBreak(),p('3. Tecnologías y estructura','H1A'),table([['Capa','Tecnología','Uso'],['Backend','.NET 8 / C# / ASP.NET Core MVC','Controladores, servicios, autenticación y salud'],['Datos','EF Core 8 + Pomelo + MySqlConnector','Modelo relacional, migraciones y transacciones'],['Base','MySQL 8.4, utf8mb4','Ventas, inventario, usuarios, auditoría y configuración'],['Web','Razor, HTML, CSS, JavaScript, Bootstrap/jQuery','Interfaz operativa en navegador'],['Servidor','IIS + ASP.NET Core Hosting Bundle 8','Hospedaje en Windows y arranque administrado'],['Agente','ASP.NET Core self-contained win-x64','Puente local de periféricos como servicio'],['Serie','System.IO.Ports','Lectura y autodetección de básculas COM'],['Seguridad','Cookie auth, Identity PasswordHasher, Data Protection','Sesión, hash de claves y secretos protegidos'],['Pruebas','xUnit + pruebas HTTP/manuales','Cálculo, tramas de báscula y cierre de instalación'],['Instalación','PowerShell + bootstrap C# + winget','IIS, runtime, MySQL, servicio y firewall']], [27*mm,60*mm,83*mm]),Spacer(1,5*mm),p('Organización lógica','H2A'),*bullets(['Controllers: superficie HTTP, autorización, antiforgery y traducción de errores.','Services: reglas de venta, inventario, caja, usuarios, manufactura y periféricos.','Data/Migrations: entidades, índices, relaciones, precisión decimal y evolución del esquema.','Integrations: serie, impresión RAW Windows, ESC/POS, ZPL y contratos de adaptadores.','Atlas.PeripheralAgent: descubrimiento y ejecución local sin dar acceso directo a la base.','installer/deploy: empaquetado, instalación, comprobaciones y generación de EXE.'])]
s += [PageBreak(),p('4. Modelo de datos y precisión','H1A'),p('El esquema se administra con migraciones EF Core y se crea/actualiza al iniciar el servidor. Las tablas principales cubren sucursales, usuarios, estaciones, categorías, productos, clientes, proveedores, compras, ventas, pagos, devoluciones, inventario, caja, auditoría, facturas, firmas, periféricos, recetas y producción.'),p('Decisiones de modelado','H2A'),table([['Decisión','Implementación','Objetivo'],['Cantidades','decimal(18,3)','Peso, volumen y unidades fraccionarias'],['Costos','decimal(18,4)','Evitar pérdida en costo unitario'],['Importes','decimal(18,2)','Moneda y redondeo comercial'],['Impuesto','decimal(7,4)','Tasas fiscales con precisión'],['SKU/código','Índices únicos por sucursal','Evitar catálogos duplicados'],['Folio','Único por sucursal','Trazabilidad de ventas'],['Operación cliente','ClientOperationId único','Idempotencia ante reintentos'],['Terminal','TerminalId/WorkstationId','Separación de cajas'],['Periférico','Sucursal + estación + clave únicos','Configuración determinista']], [37*mm,55*mm,78*mm]),Spacer(1,5*mm),p('Unidades e inventario','H2A'),p('Cada producto conserva Unit e IsWeighted. La unidad describe la presentación; IsWeighted activa el flujo de báscula. Los movimientos registran tipo, cantidad y StockAfter, formando un historial trazable en lugar de modificar existencias sin evidencia.'),callout('Integridad','Las restricciones únicas constituyen una segunda barrera además de las validaciones de aplicación. Un intento simultáneo de insertar SKU, código, folio u operación repetida termina como conflicto en lugar de producir duplicados.',colors.HexColor('#E9F8F2'))]
s += [PageBreak(),p('5. Lógica de venta y concurrencia','H1A'),p('Flujo de venta','H2A'),table([['Paso','Método lógico'],['1. Identificación','La sesión aporta sucursal, usuario y terminal.'],['2. Turno','Se exige un turno abierto del usuario en esa estación.'],['3. Carrito','Se validan productos, cantidades positivas, unidad y existencia.'],['4. Cálculo','SaleCalculator obtiene subtotal, descuento, impuesto y total con redondeo comercial.'],['5. Persistencia','Venta, líneas, pagos y movimientos de inventario se guardan en transacción.'],['6. Idempotencia','ClientOperationId permite reconocer un reintento de la misma solicitud.'],['7. Salida','Se devuelve folio; después puede imprimirse y abrir cajón según política.']], [38*mm,132*mm]),Spacer(1,5*mm),p('Control de simultaneidad','H2A'),*bullets(['Transacciones de base de datos agrupan cambios relacionados.','Apertura de turno usa aislamiento Serializable para impedir dos turnos equivalentes.','Índices únicos detienen inserciones duplicadas aun cuando dos cajas llegan al mismo tiempo.','La venta se asocia a terminal, turno, sucursal y operación cliente.','Los errores de clave duplicada se convierten en respuesta Conflict y no en venta adicional.']),p('Productos a granel','H2A'),p('Cuando IsWeighted está activo, la interfaz consulta ScaleReading en tiempo real. El analizador acepta tramas comunes con kg, g y lb, normaliza a kilogramos y rechaza ERROR/OVERLOAD. Al agregar la cantidad se integra al carrito con tres decimales y la pantalla vuelve al flujo de búsqueda.'),callout('Principio de seguridad contable','Una respuesta repetida del navegador no debe equivaler a una segunda venta. La identidad única de operación y la restricción en MySQL son la defensa principal contra doble inserción.',PALE)]
s += [PageBreak(),p('6. Inventario, devoluciones y caja','H1A'),p('Inventario','H2A'),*bullets(['Recepción de compra incrementa existencias y conserva proveedor, folio, costo y líneas.','Ajustes autorizados registran entrada, salida, corrección o merma con usuario y nota.','No se acepta una salida que produzca inventario negativo.','Producción consume componentes de receta e incrementa el producto terminado dentro de una transacción.']),p('Devoluciones parciales','H2A'),*bullets(['Se consulta la venta por folio y se calcula cuánto queda disponible por cada línea.','La solicitud indica línea, cantidad parcial, motivo y si el artículo vuelve al inventario.','Se impide devolver más de lo vendido menos devoluciones previas.','Se crea cabecera y líneas de devolución; si Restocked=true se genera movimiento de inventario.','La devolución queda ligada a venta, producto y usuario mediante auditoría.']),p('Caja','H2A'),table([['Función','Regla'],['Apertura','Fondo inicial no negativo; turno por usuario y estación.'],['Entrada/retiro','Motivo obligatorio; un retiro no supera efectivo esperado.'],['Venta en efectivo','Suma al efectivo esperado del turno.'],['Corte','Guarda esperado, contado, diferencia, hora y estado cerrado.'],['Cajón manual','Sólo Administrator/Manager, requiere motivo y crea auditoría.']], [45*mm,125*mm]),callout('Separación por caja','Un mismo usuario puede operar distintas terminales sin mezclar turnos, siempre que cada navegador conserve su identidad de estación.',colors.HexColor('#FFF3E5'))]
s += [PageBreak(),p('7. Seguridad, roles y auditoría','H1A'),table([['Control','Implementación'],['Inicio de sesión','Cookie HttpOnly, SameSite Lax, expiración deslizante de 4 horas; 12 horas si se recuerda.'],['Contraseñas','PasswordHasher de ASP.NET Identity; rehash automático cuando el algoritmo requiere actualización.'],['Primer acceso','admin@atlas.local y contraseña definida durante la instalación; no existe clave universal.'],['Autorización','Administrator, Manager y Cashier; políticas ManageInventory, CloseCash y Audit.'],['CSRF','ValidateAntiForgeryToken en operaciones POST.'],['Secretos de periféricos','IDataProtection con claves persistidas en .keys.'],['Base de datos','La aplicación usa atlas_app; root queda reservado para administración local.'],['Red MySQL','bind-address=127.0.0.1; las cajas no reciben acceso a 3306.'],['Agente','Token aleatorio de 48 caracteres y firewall limitado a la IP del servidor.'],['Auditoría','Usuarios, ventas, caja, inventario, periféricos y acciones sensibles dejan registro.']], [47*mm,123*mm]),Spacer(1,5*mm),p('Aprovisionamiento MySQL','H2A'),p('En instalación nueva se inicializa una instancia AtlasMySQL local, se define la contraseña proporcionada para root y se crea atlas_app. En una instancia existente se solicita la clave actual de root. CREATE USER IF NOT EXISTS y ALTER USER sincronizan la contraseña de atlas_app con appsettings.Production.json; sus privilegios se limitan a atlas_pos.*.'),callout('Pendiente recomendado','Para producción con requisitos elevados se recomienda habilitar HTTPS interno, firmar digitalmente los EXE, establecer rotación de secretos y guardar respaldos fuera del servidor.',colors.HexColor('#FFECEE'))]
s += [PageBreak(),p('8. Integración de periféricos','H1A'),p('Patrón aplicado','H2A'),p('El navegador no puede acceder libremente a puertos COM o al spooler. Por eso Atlas Agent se instala en cada caja como servicio automático de Windows. El servidor llama al agente autenticándose con token, y el firewall acepta sólo la IP autorizada.'),table([['Dispositivo','Métodos implementados','Observaciones'],['Báscula','Serial COM, autodetección, sondeo de tramas, kg/g/lb','Baud rate, puerto y formato varían por modelo.'],['Impresora ticket','Cola RAW de Windows, ESC/POS, TCP','Admite nombre exacto de impresora o endpoint.'],['Etiquetas','ZPL sobre TCP/adaptador público','Sujeto a lenguaje soportado por impresora.'],['Cajón','Pulso ESC/POS por impresora; manual/auto/deshabilitado','Normalmente conectado RJ11/RJ12 a la impresora.'],['Lector código','HID como teclado','No requiere SDK cuando emula teclado.']], [33*mm,68*mm,69*mm]),Spacer(1,5*mm),p('Experiencia de báscula','H2A'),*bullets(['Descubrimiento de puertos serie disponibles y prueba de configuraciones compatibles.','Lectura normalizada con estado, peso, unidad y mensaje de diagnóstico.','Persistencia por terminal para que cada caja conserve su propia báscula.','Prueba de configuración antes de considerarla lista.','Recuperación del servicio mediante política de reinicio de Windows.']),callout('Límite de compatibilidad','No se incluyeron SDK propietarios cerrados de Torrey, Rhino, Dibal, Toledo, Zebra, Epson u otros fabricantes. La compatibilidad actual se apoya en estándares públicos, drivers Windows y protocolos documentados. Cada modelo debe validarse físicamente; un SDK cerrado exige licencia, redistribuibles y hardware de prueba.',colors.HexColor('#FFF3E5'))]
s += [PageBreak(),p('9. Instaladores y operación en Windows','H1A'),p('Instalador del servidor','H2A'),*bullets(['Exige Windows 10/11 o Windows Server de 64 bits; Windows 7 está rechazado.','Comprueba administración, espacio, perfil de red y disponibilidad del puerto 8080.','Habilita IIS e instala Hosting Bundle 8 mediante winget cuando falta.','Instala o reutiliza MySQL 8.4, configura base, usuario atlas_app y cadena de conexión.','Publica en C:\\Program Files\\Atlas POS\\Server, crea Application Pool y sitio IIS.','Abre sólo TCP 8080 en perfil privado, crea acceso directo y registro de instalación.','Valida /health, /Client/Setup y la descarga real del instalador cliente.']),p('Instalador de caja','H2A'),*bullets(['Solicita IPv4 del servidor y se ejecuta con elevación UAC.','Instala AtlasPeripheralAgent como servicio automático y configura reinicios ante falla.','Genera o conserva token, restringe firewall 17420 y comprueba /health local.','Produce DATOS-DE-ESTA-CAJA.txt con URL y token para registrar la terminal.']),p('Reutilización','H2A'),p('Los dos EXE actuales son reutilizables, no se ligan a una máquina y no se eliminan automáticamente. El servidor puede ejecutarse para reparación/actualización y el cliente reemplaza el servicio conservando el token cuando es posible.'),callout('SmartScreen','Los ejecutables no están firmados digitalmente. Windows puede mostrar Editor desconocido. Deben distribuirse por un canal controlado y comprobarse mediante SHA-256.',colors.HexColor('#FFECEE'))]
s += [PageBreak(),p('10. Métodos de calidad y evidencia','H1A'),p('Pruebas automatizadas','H2A'),table([['Área','Casos cubiertos'],['Cálculo','Producto pesable, impuesto, descuento, redondeo AwayFromZero, descuento máximo y cantidad inválida.'],['Báscula','Tramas KG/kg, gramos, coma decimal, libras y rechazo de ERROR/OVERLOAD.'],['Compilación','Publicación Release del servidor y agente win-x64 self-contained.'],['Instalador','Simulación WhatIf del flujo de servidor sin modificar el equipo.']], [38*mm,132*mm]),Spacer(1,5*mm),p('Pruebas de integración realizadas','H2A'),*bullets(['Migraciones y conexión contra una instancia MySQL local.','Arranque de la aplicación y respuesta HTTP 200 en /health.','Carga de /Client/Setup y disponibilidad del EXE cliente por HTTP HEAD.','Autenticación del agente: solicitud válida 200 y token incorrecto 401.','Verificación de integridad y tamaño de los ejecutables finales.','Renderizado y revisión visual del manual de instalación.']),p('Criterios de aceptación','H2A'),*bullets(['No se declara éxito si MySQL no conecta o la aplicación no responde.','El instalador conserva registro de transcripción para diagnóstico.','El agente se elimina parcialmente si su prueba de salud falla, evitando un servicio roto.','Las validaciones físicas deben incluir venta real, peso estable, ticket, cajón y simultaneidad entre dos cajas.']),callout('Restricción del entorno de prueba','No se completó en esta estación la creación temporal del servicio Windows por falta de autorización administrativa del sistema. El proceso del agente y sus endpoints sí fueron probados; la instalación real como servicio debe comprobarse en una PC piloto con privilegios.',colors.HexColor('#FFF3E5'))]
s += [PageBreak(),p('11. Riesgos, pendientes y recomendaciones','H1A'),table([['Prioridad','Tema','Acción recomendada'],['Alta','Firma digital','Adquirir certificado de firma de código y firmar ambos EXE para reducir SmartScreen.'],['Alta','Respaldo/restore','Automatizar calendario, cifrado, retención y ensayo periódico de restauración.'],['Alta','Prueba física','Crear matriz marca/modelo/firmware/driver/cable y certificar cada periférico.'],['Alta','HTTPS','Emitir certificado interno y activar Atlas:RequireHttps si la red lo exige.'],['Media','SDK propietarios','Incorporar sólo los necesarios, con licencia y redistribución autorizada.'],['Media','Monitoreo','Alertas de /health, espacio, MySQL, IIS y servicio Atlas Agent.'],['Media','Secretos','Rotación documentada de root, atlas_app y tokens por terminal.'],['Media','Energía/red','UPS para servidor, IP fija/reserva DHCP y respaldo de configuración.'],['Baja','Compatibilidad','Windows 10 22H2/11 x64; migrar cualquier Windows 7.']], [19*mm,38*mm,113*mm]),Spacer(1,6*mm),p('Criterio para declarar producción','H2A'),p('Antes de abrir al público debe completarse una prueba piloto en el hardware objetivo: instalación limpia, reinicio, acceso desde dos cajas, venta concurrente, producto pesable, ticket, cajón, devolución parcial, merma, corte, respaldo y restauración. El resultado debe conservar fecha, modelo, driver, evidencia y responsable.'),callout('Conclusión','Atlas POS quedó estructurado como solución centralizada y extensible, con controles de concurrencia, trazabilidad y puente local de hardware. El software está preparado para piloto; la aceptación definitiva depende de certificar el entorno real y cerrar los pendientes de firma, respaldo y periféricos.',colors.HexColor('#E9F8F2'))]
